import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth, uniqueName, createRoom } from './helpers';

test.describe(`group member: open a new Ludo match`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`after a member creates a match, every group member sees it appear in the lobby with status Waiting within 5s`, async ({ browser }) => {
    // [Verifier] NOTE: the directory's RoomStatus is Pending/Active/Finished,
    // rendered by RoomList.tsx as "Setting up…"/"Open"/"Finished" — "Open"
    // is the UI's label for the spec's "Waiting" concept (linked but not yet
    // started; RoomGate governs the actual game start). We accept either
    // label here since the Pending->Active link happens automatically right
    // after creation and is not itself the thing under test.
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const creator = await ctxA.newPage();
    const observer = await ctxB.newPage();
    await loginViaHash(creator, 0);
    await loginViaHash(observer, 1);

    const matchName = uniqueName('match');
    await createRoom(creator, matchName);

    const row = observer.getByTestId('room-list-item').filter({ hasText: matchName });
    await expect(row).toBeVisible({ timeout: 5_000 });
    await expect(row.getByText(/Setting up|Open/)).toBeVisible({ timeout: 5_000 });

    await ctxA.close();
    await ctxB.close();
  });
});
